-- Aprenda se Divertindo · 136 · Equilíbrio do banco, lote 1: Sustentabilidade e IA e Inovação
-- Rode depois do 135-email-notificacao-jogo.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 11587 a 11686 (100 questões): 50 de Sustentabilidade e 50 de IA e Inovação, 10 por nível (0 a 4) em cada matéria.
-- Entram nas trilhas Geral, Policial, Tribunais, Fiscal e Administrativa.
-- Inclui temas atuais: NDC brasileira (59% a 67% até 2035), COP30 e TFFF, Lei 15.190/2025 (licenciamento), Lei 15.042/2024 (SBCE),
-- Súmulas 618 e 623 do STJ, Resolução CNJ 615/2025 (substituiu a 332/2020), PL 2.338/2023, AI Act, LC 182/2021 e Lei 14.129/2021.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 11587, "materia": "sust", "nivel": 0, "enunciado": "Desligar a luz e os aparelhos quando ninguém está usando ajuda principalmente a:", "opcoes": ["Economizar energia", "Gastar mais água", "Aumentar o lixo", "Esquentar o planeta"], "explicacao": "Apagar luzes e tirar aparelhos da tomada reduz o consumo de energia elétrica e, com isso, os impactos da geração."}, {"id": 11588, "materia": "sust", "nivel": 0, "enunciado": "A energia que vem da força dos ventos é chamada de energia:", "opcoes": ["Eólica", "Solar", "Nuclear", "Térmica a carvão"], "explicacao": "Energia eólica é gerada por turbinas movidas pelo vento. É uma fonte renovável, muito usada no Nordeste brasileiro."}, {"id": 11589, "materia": "sust", "nivel": 0, "enunciado": "Fechar a torneira enquanto escova os dentes é uma atitude que:", "opcoes": ["Economiza água", "Desperdiça energia", "Aumenta a conta de luz", "Polui o ar"], "explicacao": "Uma torneira aberta pode gastar vários litros de água por minuto. Fechá-la durante a escovação evita desperdício."}, {"id": 11590, "materia": "sust", "nivel": 0, "enunciado": "O lixo eletrônico, como celulares e pilhas velhas, deve ser:", "opcoes": ["Levado a pontos de coleta", "Jogado no lixo comum de casa, junto com restos de comida", "Queimado no quintal para não ocupar espaço", "Enterrado no jardim, longe da horta"], "explicacao": "Pilhas, baterias e eletrônicos têm substâncias tóxicas e devem voltar ao fabricante por logística reversa, em pontos de coleta próprios."}, {"id": 11591, "materia": "sust", "nivel": 0, "enunciado": "A derrubada de grandes áreas de floresta é chamada de:", "opcoes": ["Desmatamento", "Reflorestamento", "Compostagem", "Reciclagem"], "explicacao": "Desmatamento é a retirada da vegetação nativa. O contrário, plantar árvores onde havia floresta, é reflorestamento."}, {"id": 11592, "materia": "sust", "nivel": 0, "enunciado": "Transformar restos de comida e cascas de frutas em adubo é chamado de:", "opcoes": ["Compostagem", "Incineração", "Aterro sanitário", "Desmatamento"], "explicacao": "Na compostagem, a matéria orgânica se decompõe e vira adubo, reduzindo o lixo enviado aos aterros."}, {"id": 11593, "materia": "sust", "nivel": 0, "enunciado": "Usar sacola retornável no lugar de sacolas plásticas descartáveis ajuda a:", "opcoes": ["Reduzir o lixo plástico", "Aumentar o consumo de petróleo", "Poluir os rios", "Gastar mais energia"], "explicacao": "Sacolas descartáveis viram lixo rapidamente e podem parar em rios e oceanos. A retornável reduz esse resíduo."}, {"id": 11594, "materia": "sust", "nivel": 0, "enunciado": "Uma fonte de energia renovável é aquela que:", "opcoes": ["Se renova na natureza e não se esgota", "Acaba depois de alguns anos de uso contínuo", "Vem apenas do petróleo e do gás natural", "Só pode ser usada durante a noite, quando não há sol"], "explicacao": "Sol, vento e água são fontes renováveis. Petróleo, carvão e gás natural são fontes não renováveis."}, {"id": 11595, "materia": "sust", "nivel": 0, "enunciado": "Andar de bicicleta ou de transporte coletivo, em vez de carro sozinho, ajuda a:", "opcoes": ["Diminuir a poluição do ar", "Aumentar o trânsito", "Gastar mais combustível", "Esquentar os motores"], "explicacao": "Menos carros nas ruas significam menos queima de combustível, menos gases poluentes e menos congestionamento."}, {"id": 11596, "materia": "sust", "nivel": 0, "enunciado": "O Dia Mundial do Meio Ambiente é comemorado em:", "opcoes": ["5 de junho", "22 de abril", "1º de maio", "15 de novembro"], "explicacao": "A ONU instituiu o Dia Mundial do Meio Ambiente em 5 de junho, data da abertura da Conferência de Estocolmo, em 1972. O Dia da Terra é 22 de abril."}, {"id": 11597, "materia": "sust", "nivel": 1, "enunciado": "O ODS 14 da Agenda 2030 trata de:", "opcoes": ["Vida na água", "Vida terrestre", "Fome zero", "Educação de qualidade"], "explicacao": "ODS 14: conservar e usar de forma sustentável os oceanos, mares e recursos marinhos. A vida terrestre é o ODS 15."}, {"id": 11598, "materia": "sust", "nivel": 1, "enunciado": "O ODS 4 da Agenda 2030 trata de:", "opcoes": ["Educação de qualidade", "Saúde e bem-estar", "Trabalho decente", "Redução das desigualdades"], "explicacao": "ODS 4: assegurar educação inclusiva, equitativa e de qualidade. Saúde é o ODS 3; trabalho decente, o 8; redução das desigualdades, o 10."}, {"id": 11599, "materia": "sust", "nivel": 1, "enunciado": "A conferência das Nações Unidas sobre mudança do clima de 2025, a COP30, foi realizada em:", "opcoes": ["Belém (PA)", "Rio de Janeiro (RJ)", "Manaus (AM)", "Brasília (DF)"], "explicacao": "A COP30 ocorreu em novembro de 2025 em Belém, na Amazônia. A COP31, em 2026, foi em Antália, na Turquia."}, {"id": 11600, "materia": "sust", "nivel": 1, "enunciado": "A Conferência das Nações Unidas sobre Meio Ambiente e Desenvolvimento de 1992, que aprovou a Agenda 21, ficou conhecida como:", "opcoes": ["Rio-92 ou Eco-92", "Conferência de Estocolmo", "Rio+20", "Cúpula de Johannesburgo"], "explicacao": "A Rio-92 aprovou a Agenda 21 e as convenções sobre clima e biodiversidade. Estocolmo foi em 1972; Johannesburgo (Rio+10), em 2002; a Rio+20, em 2012."}, {"id": 11601, "materia": "sust", "nivel": 1, "enunciado": "Pegada hídrica é:", "opcoes": ["O volume de água usado para produzir um bem ou serviço", "A marca deixada pelas enchentes nas paredes das casas", "A quantidade de chuva que cai em uma cidade durante um ano", "O nível mínimo dos rios na época mais seca do ano"], "explicacao": "A pegada hídrica soma a água usada direta e indiretamente em toda a cadeia de produção, como na carne, no café e nas roupas."}, {"id": 11602, "materia": "sust", "nivel": 1, "enunciado": "O efeito estufa natural é importante para a vida na Terra porque:", "opcoes": ["Mantém a temperatura do planeta adequada à vida", "Destrói a camada de ozônio que protege a Terra dos raios solares", "Provoca as chuvas ácidas nas grandes cidades industriais", "Esfria o planeta durante o dia e o esquenta à noite"], "explicacao": "Sem o efeito estufa natural, a Terra seria muito fria. O problema é a intensificação desse efeito pelo excesso de gases emitidos pelas atividades humanas."}, {"id": 11603, "materia": "sust", "nivel": 1, "enunciado": "O Protocolo de Montreal, de 1987, tem como foco:", "opcoes": ["Proteger a camada de ozônio, eliminando gases como os CFCs", "Reduzir as emissões de gases de efeito estufa dos países ricos", "Proteger as florestas tropicais", "Controlar a pesca nos oceanos"], "explicacao": "O Protocolo de Montreal eliminou substâncias que destroem a camada de ozônio, como os CFCs. A redução de gases de efeito estufa foi tema do Protocolo de Kyoto (1997) e do Acordo de Paris (2015)."}, {"id": 11604, "materia": "sust", "nivel": 1, "enunciado": "No Brasil, a maior parte da energia elétrica é gerada por:", "opcoes": ["Usinas hidrelétricas", "Usinas nucleares", "Usinas a carvão", "Usinas a óleo diesel"], "explicacao": "A matriz elétrica brasileira é majoritariamente renovável, com predomínio das hidrelétricas, seguidas por eólica, biomassa e solar."}, {"id": 11605, "materia": "sust", "nivel": 1, "enunciado": "O princípio do poluidor-pagador estabelece que:", "opcoes": ["Quem polui deve arcar com os custos de prevenir e reparar os danos", "O Estado paga pelos danos ambientais causados pelas empresas privadas", "Só paga quem polui de propósito, nunca quem polui por acidente ou descuido", "A população paga uma taxa mensal para autorizar as empresas a poluir"], "explicacao": "Pelo poluidor-pagador, o custo ambiental é internalizado por quem gera a poluição (Lei 6.938/1981, art. 4º, VII)."}, {"id": 11606, "materia": "sust", "nivel": 1, "enunciado": "Créditos de carbono representam:", "opcoes": ["Uma tonelada de CO2 equivalente reduzida ou retirada da atmosfera", "Um desconto concedido na conta de energia elétrica de quem economiza", "Uma multa aplicada pelo Ibama a quem desmata área de preservação", "Um imposto federal cobrado sobre gasolina, diesel e gás de cozinha"], "explicacao": "Cada crédito equivale, em regra, a 1 tonelada de CO2 equivalente reduzida ou removida e pode ser negociado em mercados de carbono."}, {"id": 11607, "materia": "sust", "nivel": 2, "enunciado": "A Política Nacional do Meio Ambiente, que criou o Sisnama e o Conama, é a:", "opcoes": ["Lei 6.938/1981", "Lei 9.605/1998", "Lei 12.305/2010", "Lei 12.651/2012"], "explicacao": "Lei 6.938/1981: Política Nacional do Meio Ambiente. A 9.605/1998 trata dos crimes ambientais; a 12.305/2010, dos resíduos sólidos; a 12.651/2012 é o Código Florestal."}, {"id": 11608, "materia": "sust", "nivel": 2, "enunciado": "Pelo Código Florestal (Lei 12.651/2012), a área protegida coberta ou não por vegetação nativa, como as margens de rios, com função de preservar recursos hídricos e a estabilidade do solo, é a:", "opcoes": ["Área de Preservação Permanente (APP)", "Reserva Legal", "Unidade de Conservação de uso sustentável", "Terra indígena"], "explicacao": "APP é protegida pela função ambiental (margens de rios, nascentes, encostas, topos de morro). Reserva Legal é o percentual de vegetação nativa que todo imóvel rural deve manter."}, {"id": 11609, "materia": "sust", "nivel": 2, "enunciado": "O Sistema Nacional de Unidades de Conservação (SNUC) foi instituído pela:", "opcoes": ["Lei 9.985/2000", "Lei 6.938/1981", "Lei 11.428/2006", "Lei 9.433/1997"], "explicacao": "Lei 9.985/2000: SNUC. A 11.428/2006 é a Lei da Mata Atlântica e a 9.433/1997 é a Política Nacional de Recursos Hídricos."}, {"id": 11610, "materia": "sust", "nivel": 2, "enunciado": "No SNUC, as unidades de conservação dividem-se em dois grupos:", "opcoes": ["Proteção integral e uso sustentável", "Federais e municipais", "Públicas e privadas, sem subdivisões", "Florestas e reservas marinhas"], "explicacao": "Proteção integral admite apenas uso indireto dos recursos (ex.: parque nacional, estação ecológica). Uso sustentável concilia conservação e uso de parte dos recursos (ex.: APA, reserva extrativista)."}, {"id": 11611, "materia": "sust", "nivel": 2, "enunciado": "A Política Nacional de Educação Ambiental foi instituída pela Lei:", "opcoes": ["9.795/1999", "9.605/1998", "10.257/2001", "12.187/2009"], "explicacao": "Lei 9.795/1999: a educação ambiental é componente essencial e permanente da educação nacional, em todos os níveis e modalidades. A 10.257/2001 é o Estatuto da Cidade e a 12.187/2009, a Política sobre Mudança do Clima."}, {"id": 11612, "materia": "sust", "nivel": 2, "enunciado": "O princípio da precaução orienta que:", "opcoes": ["Risco de dano grave e incerteza científica não justificam adiar a proteção", "Só se deve agir depois que o dano ambiental estiver totalmente comprovado por perícia oficial", "As atividades conhecidas e consideradas seguras dispensam qualquer tipo de controle ou estudo", "Os danos ambientais devem ser apenas indenizados em dinheiro, nunca evitados de antemão"], "explicacao": "A precaução atua sobre riscos incertos (Declaração do Rio, princípio 15). A prevenção atua sobre riscos já conhecidos."}, {"id": 11613, "materia": "sust", "nivel": 2, "enunciado": "Pela Constituição Federal, todos têm direito ao meio ambiente ecologicamente equilibrado, que é:", "opcoes": ["Bem de uso comum do povo e essencial à sadia qualidade de vida", "Bem dominical da União, que pode ser vendido", "Propriedade exclusiva dos estados onde se localiza", "Direito apenas das gerações atuais"], "explicacao": "Art. 225 da CF: o meio ambiente é bem de uso comum do povo, e o dever de defendê-lo e preservá-lo para as presentes e futuras gerações é do Poder Público e da coletividade."}, {"id": 11614, "materia": "sust", "nivel": 2, "enunciado": "A Lei 14.119/2021 instituiu a Política Nacional de:", "opcoes": ["Pagamento por Serviços Ambientais", "Resíduos Sólidos e Logística Reversa", "Recursos Hídricos e Saneamento Básico", "Mudança do Clima e Mercado de Carbono"], "explicacao": "A Lei 14.119/2021 criou a Política Nacional de Pagamento por Serviços Ambientais: quem preserva ou recupera ecossistemas (protetor-recebedor) pode ser remunerado."}, {"id": 11615, "materia": "sust", "nivel": 2, "enunciado": "Na Política Nacional de Recursos Hídricos (Lei 9.433/1997), a água é definida como:", "opcoes": ["Bem de domínio público, limitado e dotado de valor econômico", "Bem privado de quem é dono do terreno onde está a nascente", "Recurso ilimitado e de uso gratuito em qualquer situação de consumo", "Bem de propriedade exclusiva dos municípios onde estão os rios"], "explicacao": "Art. 1º da Lei 9.433/1997: a água é bem de domínio público, limitado e com valor econômico; em escassez, o uso prioritário é o consumo humano e a dessedentação de animais."}, {"id": 11616, "materia": "sust", "nivel": 2, "enunciado": "A meta de neutralidade climática, assumida pelo Brasil em sua NDC, é alcançar emissões líquidas zero de gases de efeito estufa até:", "opcoes": ["2050", "2030", "2035", "2100"], "explicacao": "Na NDC apresentada em 2024, o Brasil se comprometeu a reduzir as emissões líquidas de 59% a 67% até 2035 (frente a 2005) e a alcançar a neutralidade climática até 2050."}, {"id": 11617, "materia": "sust", "nivel": 3, "enunciado": "Na NDC apresentada na COP29, o Brasil assumiu o compromisso de reduzir suas emissões líquidas de gases de efeito estufa, até 2035, em relação a 2005, entre:", "opcoes": ["59% e 67%", "37% e 43%", "20% e 25%", "80% e 90%"], "explicacao": "A nova NDC brasileira (nov/2024) fixou uma banda de 59% a 67% de redução das emissões líquidas em 2035, frente a 2005, o que equivale a 850 milhões a 1,05 bilhão de toneladas de CO2 equivalente."}, {"id": 11618, "materia": "sust", "nivel": 3, "enunciado": "Pelo Código Florestal, o imóvel rural localizado em área de floresta na Amazônia Legal deve manter, como Reserva Legal, o percentual mínimo de:", "opcoes": ["80% da área", "50% da área", "35% da área", "20% da área"], "explicacao": "Art. 12 da Lei 12.651/2012: na Amazônia Legal, 80% em área de florestas, 35% em cerrado e 20% em campos gerais; nas demais regiões do país, 20%."}, {"id": 11619, "materia": "sust", "nivel": 3, "enunciado": "A Lei Geral do Licenciamento Ambiental, que prevê modalidades como a Licença Ambiental Única (LAU) e a Licença por Adesão e Compromisso (LAC), é a:", "opcoes": ["Lei 15.190/2025", "Lei 15.042/2024", "Lei 14.119/2021", "Lei 12.651/2012"], "explicacao": "A Lei 15.190/2025 (sancionada em 8/8/2025, em vigor desde fevereiro de 2026) padronizou o licenciamento e previu licenças como LP, LI, LO, LAU, LAC, LOC e LAE. A 15.042/2024 criou o mercado regulado de carbono (SBCE)."}, {"id": 11620, "materia": "sust", "nivel": 3, "enunciado": "Na Lei 15.190/2025, a Licença por Adesão e Compromisso (LAC) se destina, em regra, a:", "opcoes": ["Atividades de pequeno ou médio porte e baixo ou médio potencial poluidor, por autodeclaração", "Grandes obras de infraestrutura com significativo impacto ambiental, como hidrelétricas e rodovias", "Empreendimentos que já funcionam sem licença, para regularizá-los perante o órgão ambiental", "Atividades estratégicas definidas pelo Conselho de Governo, com prazo prioritário de análise"], "explicacao": "A LAC é licença simplificada, por autodeclaração do empreendedor que adere a requisitos fixados pela autoridade. A regularização de quem já opera é a LOC; as atividades estratégicas, a LAE."}, {"id": 11621, "materia": "sust", "nivel": 3, "enunciado": "Pela Lei 6.938/1981, a responsabilidade civil do poluidor por danos ao meio ambiente é:", "opcoes": ["Objetiva, independendo da existência de culpa", "Subjetiva, exigindo prova de dolo", "Subsidiária, cabendo primeiro ao Estado", "Afastada quando a atividade tem licença ambiental"], "explicacao": "Art. 14, § 1º, da Lei 6.938/1981: o poluidor é obrigado, independentemente de culpa, a indenizar ou reparar os danos. A licença não afasta o dever de reparar."}, {"id": 11622, "materia": "sust", "nivel": 3, "enunciado": "Segundo o STF e o STJ, a pretensão de reparação civil do dano ambiental:", "opcoes": ["É imprescritível", "Prescreve em 5 anos", "Prescreve em 10 anos", "Prescreve em 3 anos, como as demais reparações civis"], "explicacao": "O STF fixou no Tema 999 que é imprescritível a pretensão de reparação civil de dano ambiental, entendimento já firmado também no STJ."}, {"id": 11623, "materia": "sust", "nivel": 3, "enunciado": "No SNUC, é exemplo de unidade de conservação de proteção integral:", "opcoes": ["Estação Ecológica", "Área de Proteção Ambiental", "Reserva Extrativista", "Floresta Nacional"], "explicacao": "Proteção integral: estação ecológica, reserva biológica, parque nacional, monumento natural e refúgio de vida silvestre. APA, reserva extrativista e floresta nacional são de uso sustentável."}, {"id": 11624, "materia": "sust", "nivel": 3, "enunciado": "O Fundo Florestas Tropicais para Sempre (TFFF), lançado pelo Brasil no contexto da COP30, tem como proposta:", "opcoes": ["Remunerar países tropicais por manterem suas florestas em pé", "Financiar a abertura de novas áreas para a agricultura", "Comprar terras privadas na Amazônia para o governo federal", "Substituir o Acordo de Paris"], "explicacao": "O TFFF é um mecanismo de investimento que paga países com florestas tropicais por hectare preservado, como incentivo permanente contra o desmatamento."}, {"id": 11625, "materia": "sust", "nivel": 3, "enunciado": "O Decreto 7.746/2012 trata, na administração pública federal, de:", "opcoes": ["Critérios de sustentabilidade nas contratações públicas federais", "Normas gerais sobre crimes ambientais cometidos por servidores públicos federais no exercício do cargo", "Regras para a concessão de florestas públicas federais à exploração privada", "Procedimento de licenciamento ambiental das obras realizadas pela União"], "explicacao": "O Decreto 7.746/2012 estabelece critérios e práticas de sustentabilidade nas contratações da administração federal, como menor impacto sobre recursos naturais e maior eficiência no uso de água e energia."}, {"id": 11626, "materia": "sust", "nivel": 3, "enunciado": "A diferença entre os princípios da prevenção e da precaução é que:", "opcoes": ["A prevenção cuida de riscos conhecidos; a precaução, de riscos ainda incertos", "A prevenção vale só para empresas privadas, e a precaução, só para o próprio Estado", "A precaução exige prova do dano para agir, e a prevenção dispensa qualquer estudo técnico", "Ambos são sinônimos na legislação brasileira e não há diferença prática entre eles"], "explicacao": "Prevenção: o risco é conhecido (por isso se exige EIA, por exemplo). Precaução: há incerteza científica, mas risco de dano grave ou irreversível."}, {"id": 11627, "materia": "sust", "nivel": 4, "enunciado": "Segundo a Súmula 618 do STJ, nas ações de degradação ambiental:", "opcoes": ["Aplica-se a inversão do ônus da prova", "O ônus da prova é sempre do Ministério Público", "É vedada a produção de prova pericial", "A prova deve ser produzida exclusivamente pelo órgão licenciador"], "explicacao": "Súmula 618 do STJ: a inversão do ônus da prova aplica-se às ações de degradação ambiental. Cabe ao réu demonstrar que sua atividade não causou o dano."}, {"id": 11628, "materia": "sust", "nivel": 4, "enunciado": "Pela Súmula 623 do STJ, as obrigações ambientais:", "opcoes": ["Têm natureza propter rem e podem ser cobradas do proprietário atual e/ou dos anteriores", "Extinguem-se com a venda do imóvel, cabendo apenas ao antigo dono reparar o dano causado", "Só alcançam quem causou diretamente o dano, nunca o novo proprietário ou possuidor da área", "Dependem de averbação prévia na matrícula do imóvel para serem exigidas do adquirente"], "explicacao": "Súmula 623 do STJ: as obrigações ambientais possuem natureza propter rem, sendo admissível cobrá-las do proprietário ou possuidor atual e/ou dos anteriores, à escolha do credor."}, {"id": 11629, "materia": "sust", "nivel": 4, "enunciado": "No Sistema Brasileiro de Comércio de Emissões (SBCE), criado pela Lei 15.042/2024, a Cota Brasileira de Emissões (CBE) é:", "opcoes": ["Ativo que dá direito a emitir 1 tCO2e, distribuído gratuita ou onerosamente", "Multa aplicada pelo órgão gestor a quem ultrapassa o limite anual de emissões permitido", "Certificado de reflorestamento emitido pelo Ibama a pequenos produtores rurais cadastrados", "Imposto federal cobrado sobre combustíveis fósseis para financiar a transição energética"], "explicacao": "No SBCE, o modelo é de limite e comércio (cap and trade): os operadores recebem CBEs (direitos de emitir) e podem usar Certificados de Redução ou Remoção Verificada de Emissões (CRVE) para cumprir suas obrigações."}, {"id": 11630, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei 15.042/2024, ficam sujeitos ao dever de submeter plano de monitoramento e relato de emissões ao SBCE os operadores que emitem acima de:", "opcoes": ["10.000 toneladas de CO2 equivalente por ano", "1.000 toneladas de CO2 equivalente por ano", "100.000 toneladas de CO2 equivalente por ano", "1 milhão de toneladas de CO2 equivalente por ano"], "explicacao": "A Lei 15.042/2024 exige monitoramento e relato de quem emite acima de 10 mil tCO2e/ano; acima de 25 mil tCO2e/ano, o operador também deve conciliar periodicamente suas obrigações (entregar cotas)."}, {"id": 11631, "materia": "sust", "nivel": 4, "enunciado": "Pela Constituição Federal, após a Emenda Constitucional 96/2017, não se consideram cruéis as práticas desportivas que utilizem animais, desde que:", "opcoes": ["Sejam manifestações culturais registradas como bem imaterial e regulamentadas por lei que assegure o bem-estar animal", "Sejam realizadas apenas em propriedades privadas, sem cobrança de ingresso e sem transmissão por televisão ou internet", "Tenham autorização prévia do Ibama, presença de veterinário e duração máxima de um único dia de evento", "Ocorram somente em municípios com menos de 50 mil habitantes e fora do período de reprodução das espécies"], "explicacao": "Art. 225, § 7º, da CF (EC 96/2017, após o STF julgar a vaquejada na ADI 4983): práticas desportivas com animais que sejam manifestações culturais registradas como bem imaterial não são consideradas cruéis, desde que regulamentadas por lei específica que assegure o bem-estar dos animais."}, {"id": 11632, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei Complementar 140/2011, o licenciamento ambiental de empreendimentos localizados ou desenvolvidos em terras indígenas compete:", "opcoes": ["À União", "Ao Estado onde se localiza o empreendimento", "Ao Município", "À Fundação Nacional dos Povos Indígenas (Funai)"], "explicacao": "Art. 7º, XIV, c, da LC 140/2011: cabe à União licenciar empreendimentos em terras indígenas. A Funai participa como órgão interveniente, mas não licencia."}, {"id": 11633, "materia": "sust", "nivel": 4, "enunciado": "No ICMS Ecológico, adotado por vários estados brasileiros:", "opcoes": ["Parte do ICMS repassado aos municípios é distribuída por critérios ambientais", "O contribuinte paga uma alíquota extra de ICMS sobre todos os produtos considerados poluentes", "O ICMS deixa de ser cobrado nas operações com produtos recicláveis e biodegradáveis", "A União repassa aos estados um percentual do ICMS proporcional à área preservada"], "explicacao": "No ICMS Ecológico, a lei estadual usa critérios como unidades de conservação e saneamento para repartir aos municípios parte dos 25% do ICMS que lhes cabem (art. 158, IV e § 2º, da CF)."}, {"id": 11634, "materia": "sust", "nivel": 4, "enunciado": "No Pagamento por Serviços Ambientais (Lei 14.119/2021), quem recebe o pagamento é o:", "opcoes": ["O provedor do serviço, que mantém ou recupera o ambiente", "O pagador, que usa e se beneficia do serviço ambiental prestado", "O órgão ambiental que fiscaliza o cumprimento das obrigações do contrato", "O Ministério Público, que acompanha a execução e a aplicação dos recursos"], "explicacao": "Na Lei 14.119/2021, o provedor (quem preserva ou recupera) recebe; o pagador (poder público, organização ou pessoa física que se beneficia) paga. É a aplicação do princípio do protetor-recebedor."}, {"id": 11635, "materia": "ia", "nivel": 0, "enunciado": "Assistentes de voz que respondem a comandos falados, como “qual a previsão do tempo?”, usam:", "opcoes": ["Inteligência artificial", "Apenas calculadora", "Rádio AM", "Planilha eletrônica"], "explicacao": "Assistentes de voz usam IA para reconhecer a fala, entender o pedido e responder."}, {"id": 11636, "materia": "ia", "nivel": 0, "enunciado": "Quando um aplicativo de streaming sugere filmes parecidos com os que você assistiu, ele está usando:", "opcoes": ["Um sistema de recomendação", "Um antivírus que protege o aplicativo de ataques", "Um editor de texto instalado no aparelho", "Um firewall que bloqueia conexões suspeitas"], "explicacao": "Sistemas de recomendação usam dados do seu histórico e de outros usuários para sugerir conteúdos com mais chance de agradar."}, {"id": 11637, "materia": "ia", "nivel": 0, "enunciado": "Ao receber uma resposta de uma ferramenta de IA para um trabalho, o mais correto é:", "opcoes": ["Conferir as informações em fontes confiáveis", "Copiar sem ler", "Acreditar em tudo, porque a máquina não erra", "Apagar a pergunta para ninguém ver"], "explicacao": "Ferramentas de IA podem errar ou inventar dados. Conferir em fontes confiáveis é indispensável."}, {"id": 11638, "materia": "ia", "nivel": 0, "enunciado": "O golpe em que criminosos imitam a voz de um parente usando IA para pedir dinheiro é chamado de:", "opcoes": ["Clonagem de voz", "Backup", "Atualização de sistema", "Download"], "explicacao": "Com poucos segundos de áudio, ferramentas de IA conseguem imitar vozes. Desconfie de pedidos urgentes de dinheiro e confirme por outro canal."}, {"id": 11639, "materia": "ia", "nivel": 0, "enunciado": "A tecnologia que permite desbloquear o celular olhando para a tela é o:", "opcoes": ["Reconhecimento facial", "Bluetooth de baixa energia ligado ao relógio", "Rede Wi-Fi de casa ou do trabalho", "GPS que identifica a localização do aparelho"], "explicacao": "O reconhecimento facial usa IA para comparar o rosto captado pela câmera com o modelo cadastrado."}, {"id": 11640, "materia": "ia", "nivel": 0, "enunciado": "Robôs aspiradores que desviam de móveis e mapeiam a casa são um exemplo de:", "opcoes": ["Uso de IA e sensores", "Uso de energia nuclear em pequena escala", "Impressão 3D de peças de reposição", "Uma rede social de compartilhamento de fotos"], "explicacao": "Esses robôs combinam sensores e algoritmos para perceber o ambiente e decidir o trajeto."}, {"id": 11641, "materia": "ia", "nivel": 0, "enunciado": "Traduzir automaticamente um texto do inglês para o português em um aplicativo é um uso de:", "opcoes": ["Inteligência artificial", "Um antivírus instalado no celular", "Uma planilha eletrônica com fórmulas", "Um pen drive com um dicionário salvo"], "explicacao": "Tradutores automáticos usam processamento de linguagem natural, uma área da IA."}, {"id": 11642, "materia": "ia", "nivel": 0, "enunciado": "Inovação é:", "opcoes": ["Criar ou melhorar algo que gere valor ou resolva um problema", "Copiar sempre, sem adaptação, a solução usada por outra empresa", "Comprar o computador mais caro disponível no mercado", "Manter tudo exatamente como sempre foi feito, sem mudanças"], "explicacao": "Inovar é transformar ideias em soluções novas ou melhores que gerem valor, seja em produtos, serviços ou processos."}, {"id": 11643, "materia": "ia", "nivel": 0, "enunciado": "Um chatbot de atendimento de um órgão público serve, principalmente, para:", "opcoes": ["Responder dúvidas frequentes a qualquer hora", "Substituir todas as leis e normas que regem o órgão", "Julgar processos administrativos sozinho, sem servidores", "Desligar automaticamente os computadores no fim do expediente"], "explicacao": "Chatbots atendem perguntas repetitivas 24 horas por dia, liberando servidores para casos mais complexos."}, {"id": 11644, "materia": "ia", "nivel": 0, "enunciado": "Dar muitos exemplos de fotos de gatos para um programa aprender a reconhecer gatos é uma forma de:", "opcoes": ["Treinar um modelo de IA", "Formatar o computador", "Instalar um antivírus", "Criar uma senha"], "explicacao": "Modelos de IA aprendem padrões a partir de exemplos. Quanto mais variados e corretos os dados, melhor o aprendizado."}, {"id": 11645, "materia": "ia", "nivel": 1, "enunciado": "No aprendizado não supervisionado, o modelo:", "opcoes": ["Encontra padrões e agrupamentos em dados sem rótulos", "Aprende com dados já rotulados com a resposta certa", "Recebe recompensas e punições por tentativa e erro", "Segue regras escritas uma a uma pelo programador"], "explicacao": "Sem rótulos, o modelo agrupa dados semelhantes (clusterização), como segmentar clientes por comportamento. Dados rotulados caracterizam o supervisionado; recompensas, o aprendizado por reforço."}, {"id": 11646, "materia": "ia", "nivel": 1, "enunciado": "Engenharia de prompt é:", "opcoes": ["Formular instruções claras para obter boas respostas da IA", "A fabricação e a montagem de peças de hardware para computadores pessoais", "A manutenção preventiva das redes elétricas de alta tensão nas cidades", "A programação de jogos de videogame em linguagem de máquina de baixo nível"], "explicacao": "Dar contexto, objetivo, formato da resposta e exemplos melhora muito o resultado de modelos de linguagem."}, {"id": 11647, "materia": "ia", "nivel": 1, "enunciado": "Fornecer à IA alguns exemplos de perguntas e respostas no próprio prompt, para que ela siga o padrão, é a técnica chamada de:", "opcoes": ["Few-shot (poucos exemplos)", "Overfitting (sobreajuste do modelo)", "Backup incremental dos arquivos", "Criptografia de ponta a ponta"], "explicacao": "No few-shot, o prompt traz alguns exemplos; no zero-shot, nenhum. Overfitting é um problema de treinamento, não uma técnica de prompt."}, {"id": 11648, "materia": "ia", "nivel": 1, "enunciado": "A chamada IA estreita (ou fraca) é aquela que:", "opcoes": ["Executa bem tarefas específicas, como reconhecer imagens ou traduzir", "Tem consciência e sentimentos iguais aos humanos", "Realiza qualquer tarefa intelectual humana em qualquer área", "Não precisa de dados para funcionar"], "explicacao": "Todas as IAs em uso hoje são estreitas. A IA geral, capaz de qualquer tarefa intelectual humana, ainda é objeto de pesquisa e debate."}, {"id": 11649, "materia": "ia", "nivel": 1, "enunciado": "Phishing feito com ajuda de IA é mais perigoso porque:", "opcoes": ["As mensagens ficam mais convincentes e personalizadas", "A IA desativa automaticamente o antivírus instalado no computador da vítima", "O golpe só funciona em computadores antigos, sem atualização do sistema", "A vítima é obrigada por lei a responder à mensagem em até 24 horas"], "explicacao": "A IA gera textos bem escritos e personalizados, eliminando sinais clássicos de golpe, como erros de português."}, {"id": 11650, "materia": "ia", "nivel": 1, "enunciado": "Um sistema especialista, uma das primeiras formas de IA, funciona com base em:", "opcoes": ["Regras do tipo “se... então” criadas por especialistas", "Redes neurais profundas com bilhões de parâmetros treinados na internet", "Imagens de satélite processadas em tempo real por supercomputadores", "Sorteio aleatório de respostas a partir de um banco de frases prontas"], "explicacao": "Sistemas especialistas usam bases de regras e de conhecimento definidas por humanos. Não aprendem sozinhos com dados, como o aprendizado de máquina."}, {"id": 11651, "materia": "ia", "nivel": 1, "enunciado": "Na Resolução CNJ 615/2025, que hoje rege o uso de IA no Poder Judiciário, a supervisão das soluções de IA:", "opcoes": ["Deve ser humana, com possibilidade de revisão pelo magistrado", "Pode ser dispensada quando a IA tiver alta precisão", "Cabe exclusivamente às empresas fornecedoras", "Só é exigida em processos criminais"], "explicacao": "A Resolução CNJ 615/2025, que substituiu a 332/2020, exige supervisão humana efetiva e transparência no uso de IA nos tribunais."}, {"id": 11652, "materia": "ia", "nivel": 1, "enunciado": "A Resolução CNJ 615/2025 substituiu, como norma geral sobre IA no Judiciário, a Resolução CNJ:", "opcoes": ["332/2020", "395/2021", "433/2021", "125/2010"], "explicacao": "A Resolução 615, de 11/3/2025, atualizou e substituiu a 332/2020, incorporando regras sobre IA generativa e grandes modelos de linguagem. A 395/2021 trata de gestão da inovação; a 433/2021, de meio ambiente."}, {"id": 11653, "materia": "ia", "nivel": 1, "enunciado": "Em IA, dados de treinamento são:", "opcoes": ["Os exemplos usados para o modelo aprender padrões", "As senhas e credenciais usadas para acessar o sistema", "Os relatórios de erro gerados automaticamente pelo computador", "As notas fiscais emitidas na compra das licenças do software"], "explicacao": "Os dados de treinamento alimentam o aprendizado. Se forem enviesados ou de baixa qualidade, o modelo reproduz esses problemas."}, {"id": 11654, "materia": "ia", "nivel": 1, "enunciado": "Um laboratório de inovação no setor público costuma usar a abordagem de:", "opcoes": ["Testar soluções em pequena escala antes de expandi-las", "Contratar uma solução pronta sem ouvir os usuários", "Esperar uma lei nova antes de qualquer mudança", "Proibir o uso de tecnologia nos processos"], "explicacao": "Laboratórios de inovação trabalham com experimentação, protótipos e participação dos usuários para reduzir riscos antes de ampliar a solução."}, {"id": 11655, "materia": "ia", "nivel": 2, "enunciado": "Embeddings, em modelos de IA, são:", "opcoes": ["Vetores numéricos que representam o significado de textos", "Imagens decorativas inseridas automaticamente em documentos e apresentações", "Senhas criptografadas dos usuários guardadas no banco de dados", "Cabos de fibra óptica que interligam os servidores do data center"], "explicacao": "Com embeddings, textos de sentido parecido ficam próximos no espaço vetorial, o que permite buscas por significado, como no RAG."}, {"id": 11656, "materia": "ia", "nivel": 2, "enunciado": "Ajustar um modelo de IA já treinado, usando um conjunto menor de dados de uma área específica, é chamado de:", "opcoes": ["Fine-tuning (ajuste fino)", "Overfitting (sobreajuste do modelo)", "Phishing direcionado (spear phishing)", "Deepfake de voz e imagem"], "explicacao": "O fine-tuning adapta um modelo fundacional a uma tarefa ou domínio (ex.: textos jurídicos), sem treinar do zero."}, {"id": 11657, "materia": "ia", "nivel": 2, "enunciado": "O ataque em que instruções maliciosas escondidas em um texto fazem um sistema de IA ignorar suas regras é chamado de:", "opcoes": ["Injeção de prompt (prompt injection)", "Negação de serviço", "Força bruta", "Engenharia reversa de hardware"], "explicacao": "Na injeção de prompt, o conteúdo processado pela IA (um site, um e-mail) traz comandos que tentam desviar o comportamento do sistema."}, {"id": 11658, "materia": "ia", "nivel": 2, "enunciado": "Em modelos de linguagem, o parâmetro “temperatura” controla:", "opcoes": ["O grau de aleatoriedade das respostas", "A velocidade de processamento do chip gráfico do servidor", "O aquecimento físico dos servidores durante o processamento", "O número máximo de usuários conectados ao mesmo tempo"], "explicacao": "Temperatura baixa gera respostas mais previsíveis e repetíveis; temperatura alta gera respostas mais variadas e criativas."}, {"id": 11659, "materia": "ia", "nivel": 2, "enunciado": "No AI Act da União Europeia, sistemas que manipulam pessoas de forma prejudicial ou fazem pontuação social pelo governo são classificados como de:", "opcoes": ["Risco inaceitável, e por isso proibidos", "Alto risco, permitidos com obrigações", "Risco limitado, só com aviso ao usuário", "Risco mínimo, sem obrigações"], "explicacao": "O AI Act tem quatro níveis: inaceitável (proibido), alto (obrigações rigorosas), limitado (transparência) e mínimo. Pontuação social e manipulação estão entre as práticas proibidas."}, {"id": 11660, "materia": "ia", "nivel": 2, "enunciado": "O PL 2.338/2023, que propõe o Marco Legal da Inteligência Artificial no Brasil, adota uma abordagem baseada em:", "opcoes": ["Riscos, com regras mais rígidas para sistemas de alto risco", "Proibição total do uso de inteligência artificial pelo setor público", "Liberação completa, sem nenhuma regra, para estimular a inovação", "Autorização prévia do STF para cada sistema colocado em operação"], "explicacao": "O PL 2.338/2023, aprovado no Senado e em análise na Câmara, classifica os sistemas por grau de risco e impõe obrigações proporcionais, nos moldes do modelo europeu."}, {"id": 11661, "materia": "ia", "nivel": 2, "enunciado": "Na avaliação de um classificador, a acurácia mede:", "opcoes": ["A proporção de acertos sobre o total de previsões", "A velocidade de processamento por segundo", "O número de parâmetros do modelo", "O custo de energia do treinamento"], "explicacao": "Acurácia = acertos / total. Em dados desbalanceados, ela pode enganar, por isso também se usam precisão e revocação (recall)."}, {"id": 11662, "materia": "ia", "nivel": 2, "enunciado": "A Lei 14.129/2021, que trata do Governo Digital, prevê, entre seus princípios:", "opcoes": ["Serviços públicos digitais, com linguagem clara e foco no cidadão", "A proibição do atendimento presencial em qualquer órgão público do país", "O fim do uso de dados pessoais pelo poder público em qualquer hipótese", "A cobrança obrigatória de taxa pelo acesso aos serviços públicos digitais"], "explicacao": "A Lei 14.129/2021 busca desburocratizar e digitalizar serviços, com foco no usuário, transparência e dados abertos, sem eliminar o atendimento presencial para quem precisa."}, {"id": 11663, "materia": "ia", "nivel": 2, "enunciado": "O Marco Legal das Startups e do Empreendedorismo Inovador foi instituído pela:", "opcoes": ["Lei Complementar 182/2021", "Lei 10.973/2004 (Lei de Inovação)", "Lei 13.709/2018 (LGPD)", "Lei 14.133/2021 (Licitações)"], "explicacao": "LC 182/2021: Marco Legal das Startups, com ambiente regulatório experimental (sandbox) e contratação de soluções inovadoras pelo Estado. A 10.973/2004 é a Lei de Inovação; a 13.709/2018, a LGPD."}, {"id": 11664, "materia": "ia", "nivel": 2, "enunciado": "O ambiente regulatório experimental (sandbox regulatório) permite que:", "opcoes": ["Empresas testem inovações por prazo certo, com regras flexíveis", "Qualquer empresa funcione sem fiscalização nenhuma por tempo indeterminado no país", "O governo proíba novas tecnologias antes mesmo de testá-las com consumidores reais", "Os consumidores sejam cobrados por lei para participar dos testes das inovações"], "explicacao": "No sandbox (LC 182/2021, art. 11), o regulador autoriza temporariamente modelos inovadores sob condições especiais e acompanhamento."}, {"id": 11665, "materia": "ia", "nivel": 3, "enunciado": "Em um sistema de IA que identifica suspeitos, a métrica revocação (recall) mede:", "opcoes": ["Entre os casos realmente positivos, quantos o sistema conseguiu identificar", "Entre os casos que o sistema apontou como positivos, quantos estavam certos", "O tempo médio de resposta do sistema", "A quantidade de dados usada no treinamento"], "explicacao": "Recall = verdadeiros positivos / (verdadeiros positivos + falsos negativos). Já a precisão = verdadeiros positivos / tudo o que foi apontado como positivo."}, {"id": 11666, "materia": "ia", "nivel": 3, "enunciado": "Um sistema de reconhecimento facial apontou 100 pessoas como procuradas, mas só 60 eram de fato procuradas. A precisão do sistema nesse teste foi de:", "opcoes": ["60%", "40%", "100%", "160%"], "explicacao": "Precisão = verdadeiros positivos / total apontado = 60 / 100 = 60%. As outras 40 abordagens seriam falsos positivos."}, {"id": 11667, "materia": "ia", "nivel": 3, "enunciado": "Dividir os dados em treino, validação e teste serve para:", "opcoes": ["Avaliar o modelo em dados que ele não viu no aprendizado", "Aumentar o número de parâmetros do modelo a cada nova rodada de treino", "Garantir que o modelo memorize todos os exemplos do conjunto de dados", "Reduzir o custo de energia elétrica dos servidores durante o treino"], "explicacao": "O conjunto de teste mede o desempenho real em dados novos e ajuda a detectar overfitting; a validação ajuda a ajustar hiperparâmetros."}, {"id": 11668, "materia": "ia", "nivel": 3, "enunciado": "Na Resolução CNJ 615/2025, os riscos das soluções de IA no Judiciário são classificados, de modo geral, em:", "opcoes": ["Alto risco e baixo risco, com exigências proporcionais", "Risco zero e risco total, sem categorias intermediárias", "Riscos civis, penais e trabalhistas, conforme a matéria do processo", "Risco federal e risco estadual, conforme o ramo da Justiça"], "explicacao": "A Resolução 615/2025 adota categorização de riscos (alto e baixo), com avaliação de impacto, auditoria e monitoramento mais rígidos para soluções de alto risco."}, {"id": 11669, "materia": "ia", "nivel": 3, "enunciado": "Pela Resolução CNJ 615/2025, o uso de IA generativa por magistrados e servidores deve observar que:", "opcoes": ["O magistrado continua responsável pelas decisões tomadas com apoio da IA", "A decisão gerada pela IA dispensa revisão humana", "Os modelos podem ser alimentados livremente com dados sigilosos", "A IA pode proferir sentenças sozinha em causas simples"], "explicacao": "A resolução trata de IA generativa e grandes modelos de linguagem, exigindo supervisão humana, proteção de dados e responsabilidade do usuário pelas decisões."}, {"id": 11670, "materia": "ia", "nivel": 3, "enunciado": "A Lei de Inovação (Lei 10.973/2004) define o Núcleo de Inovação Tecnológica (NIT) como:", "opcoes": ["Estrutura da ICT que gere sua política de inovação", "Órgão federal responsável por conceder patentes e registrar marcas no Brasil", "Fundo público federal que financia startups em fase inicial de operação", "Laboratório privado credenciado para testes de segurança de software"], "explicacao": "O NIT cuida da gestão da política de inovação da ICT (universidade ou instituto de pesquisa), incluindo patentes e transferência de tecnologia. Patentes são concedidas pelo INPI."}, {"id": 11671, "materia": "ia", "nivel": 3, "enunciado": "No Marco Legal das Startups (LC 182/2021), o Contrato Público para Solução Inovadora (CPSI) é firmado após:", "opcoes": ["Licitação em modalidade especial para testar soluções inovadoras", "Pregão eletrônico pelo critério de menor preço global por item", "Dispensa de licitação em qualquer valor, por se tratar de inovação", "Concurso de projetos arquitetônicos com prêmio aos vencedores"], "explicacao": "A LC 182/2021 criou modalidade especial de licitação para o teste de soluções inovadoras; o vencedor celebra o CPSI, com vigência limitada e valor máximo previsto em lei."}, {"id": 11672, "materia": "ia", "nivel": 3, "enunciado": "O conceito de “alucinação” é especialmente perigoso no uso de IA para pesquisa jurídica porque o modelo pode:", "opcoes": ["Citar leis, súmulas ou julgados que não existem", "Deixar o computador mais lento durante a pesquisa e travar o navegador", "Apagar os arquivos e documentos salvos pelo usuário no computador", "Bloquear o acesso à internet do órgão até que o sistema seja reiniciado"], "explicacao": "Há casos reais de petições com precedentes inventados por IA. Toda citação gerada deve ser conferida na fonte oficial."}, {"id": 11673, "materia": "ia", "nivel": 3, "enunciado": "A técnica RAG reduz alucinações porque:", "opcoes": ["Ancora a resposta em documentos recuperados de fonte confiável", "Desliga por completo a criatividade e a capacidade de redação do modelo", "Aumenta a temperatura do modelo para gerar respostas mais variadas", "Impede que o usuário faça perguntas abertas ou fora de um roteiro fixo"], "explicacao": "No RAG, o sistema busca trechos relevantes (por exemplo, por embeddings) e os entrega ao modelo, que responde ancorado nessas fontes, inclusive citando-as."}, {"id": 11674, "materia": "ia", "nivel": 3, "enunciado": "Na Lei 14.129/2021 (Governo Digital), os laboratórios de inovação são espaços destinados a:", "opcoes": ["Colaboração entre sociedade e governo para criar soluções públicas", "Guardar equipamentos de informática apreendidos em operações policiais", "Treinamento militar e de defesa pessoal para servidores públicos civis", "Arquivo permanente de processos físicos antigos já digitalizados"], "explicacao": "A Lei 14.129/2021 prevê que os entes podem instituir laboratórios de inovação, abertos à participação da sociedade, para desenvolver soluções e tecnologias para a gestão pública."}, {"id": 11675, "materia": "ia", "nivel": 4, "enunciado": "Em um sistema de triagem de denúncias, priorizar a revocação (recall) em vez da precisão significa:", "opcoes": ["Aceitar mais falsos positivos para deixar escapar o mínimo de casos reais", "Aceitar mais casos reais perdidos para reduzir alarmes falsos", "Ignorar completamente os falsos positivos e falsos negativos", "Aumentar a velocidade do sistema, sem efeito nos erros"], "explicacao": "Há um equilíbrio (trade-off): aumentar o recall reduz falsos negativos, mas costuma elevar os falsos positivos. Em triagem de casos graves, perder um caso real costuma custar mais caro."}, {"id": 11676, "materia": "ia", "nivel": 4, "enunciado": "A métrica F1, usada para avaliar classificadores, corresponde à:", "opcoes": ["Média harmônica entre precisão e revocação", "Média aritmética entre acurácia e velocidade", "Soma de falsos positivos e falsos negativos", "Proporção de dados usados no treinamento"], "explicacao": "F1 = 2 × (precisão × revocação) / (precisão + revocação). Ela pune modelos que vão muito bem em uma métrica e mal na outra."}, {"id": 11677, "materia": "ia", "nivel": 4, "enunciado": "Pelo AI Act da União Europeia, sistemas de IA usados na administração da justiça e na aplicação da lei são, em regra, classificados como de:", "opcoes": ["Alto risco", "Risco mínimo", "Risco limitado", "Risco inaceitável, sempre proibidos"], "explicacao": "O AI Act lista como de alto risco, entre outros, usos na aplicação da lei, migração, emprego e administração da justiça, com exigências de gestão de riscos, qualidade de dados, documentação e supervisão humana."}, {"id": 11678, "materia": "ia", "nivel": 4, "enunciado": "O fenômeno em que um modelo treinado com dados de um período perde desempenho porque o mundo mudou (por exemplo, novos tipos de golpe) é chamado de:", "opcoes": ["Deriva de dados (data drift)", "Overfitting (sobreajuste do modelo)", "Fine-tuning (ajuste fino supervisionado)", "Engenharia de prompt com poucos exemplos"], "explicacao": "Na deriva, a distribuição dos dados reais se afasta da dos dados de treino. Por isso modelos em produção precisam de monitoramento e retreinamento."}, {"id": 11679, "materia": "ia", "nivel": 4, "enunciado": "Na LGPD, o direito de solicitar a revisão de decisões tomadas unicamente com base em tratamento automatizado, como a definição de perfil de crédito:", "opcoes": ["Está no art. 20 e inclui o direito a informações sobre os critérios usados", "Só existe quando a decisão automatizada for tomada por órgão público, nunca por empresas privadas", "Exige que a revisão seja feita sempre por uma pessoa natural, por força do texto atual da lei", "Foi revogado pela Resolução CNJ 615/2025, que passou a regular toda decisão automatizada"], "explicacao": "Art. 20 da LGPD: o titular pode pedir revisão de decisões exclusivamente automatizadas e informações sobre critérios e procedimentos. A exigência de revisão por pessoa natural foi vetada no texto final."}, {"id": 11680, "materia": "ia", "nivel": 4, "enunciado": "A ideia de que vieses podem surgir não só dos dados, mas também das escolhas de quem define o problema, as variáveis e a métrica de sucesso, indica que:", "opcoes": ["Mitigar vieses exige revisar todo o ciclo de vida do sistema, não só os dados", "Basta aumentar o volume de dados de treinamento para eliminar qualquer viés existente", "Modelos matemáticos são sempre neutros, pois apenas fazem cálculos objetivos", "O viés só existe em sistemas de reconhecimento facial, e não em outros modelos"], "explicacao": "Vieses podem entrar na formulação do problema, na coleta, na rotulagem, na escolha de variáveis substitutas (proxies) e na métrica. Por isso normas como a Resolução CNJ 615/2025 exigem avaliação e auditoria contínuas."}, {"id": 11681, "materia": "ia", "nivel": 4, "enunciado": "Usar o CEP de moradia como variável em um modelo de risco criminal pode gerar discriminação indireta porque:", "opcoes": ["O CEP pode funcionar como variável substituta (proxy) de raça e renda", "O CEP não tem nenhuma relação com características sociais", "Modelos não conseguem processar números", "A LGPD proíbe qualquer uso de endereço"], "explicacao": "Mesmo sem usar raça diretamente, variáveis correlacionadas (proxies) podem reproduzir desigualdades históricas, como a concentração do policiamento em certos bairros."}, {"id": 11682, "materia": "ia", "nivel": 4, "enunciado": "Na Lei 10.973/2004 (Lei de Inovação), as Instituições Científicas, Tecnológicas e de Inovação (ICTs) públicas podem:", "opcoes": ["Firmar acordos de parceria para pesquisa e desenvolvimento conjuntos", "Conceder patentes diretamente aos pesquisadores, sem qualquer participação do INPI", "Vender livremente bens públicos sem licitação ou qualquer outro procedimento", "Contratar servidores sem concurso público para cargos efetivos de pesquisador"], "explicacao": "A Lei de Inovação autoriza a ICT a firmar acordos de parceria, compartilhar laboratórios e transferir tecnologia, com divisão da titularidade da propriedade intelectual e dos resultados."}, {"id": 11683, "materia": "ia", "nivel": 4, "enunciado": "Em relação a modelos de linguagem, a “janela de contexto” limitada pode causar o problema de:", "opcoes": ["O modelo “esquecer” trechos de documentos longos", "O computador superaquecer e desligar no meio da resposta", "A resposta sair sempre em inglês, mesmo com pergunta em português", "O modelo apagar o histórico de navegação e os favoritos do usuário"], "explicacao": "Tudo o que excede a janela de contexto não é considerado. Por isso documentos extensos são divididos em partes ou tratados por técnicas como RAG."}, {"id": 11684, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei 9.605/1998, a pessoa jurídica constituída ou utilizada preponderantemente para permitir, facilitar ou ocultar crime ambiental:", "opcoes": ["Terá liquidação forçada, e seu patrimônio irá ao Fundo Penitenciário Nacional", "Recebe apenas multa, sem qualquer efeito sobre sua existência ou sobre o seu patrimônio", "Fica isenta de pena se o crime tiver sido praticado por um de seus empregados sem ordem expressa", "Tem a pena convertida em advertência na primeira condenação, se reparar o dano em 30 dias"], "explicacao": "Art. 24 da Lei 9.605/1998: o patrimônio dessa pessoa jurídica é considerado instrumento do crime e perdido em favor do Fundo Penitenciário Nacional, com liquidação forçada."}, {"id": 11685, "materia": "sust", "nivel": 4, "enunciado": "Pela Lei Complementar 140/2011, o licenciamento ambiental das atividades ou empreendimentos que causem ou possam causar impacto ambiental de âmbito local compete:", "opcoes": ["Aos Municípios, segundo tipologia definida pelos Conselhos Estaduais de Meio Ambiente", "À União, por meio do Ibama, em todos os casos, independentemente do porte ou da localização", "Aos Estados, sem qualquer participação dos Municípios em nenhuma etapa do processo", "Ao Conama, que licencia diretamente qualquer atividade de impacto local em todo o país"], "explicacao": "Art. 9º, XIV, a, da LC 140/2011: cabe ao Município licenciar atividades de impacto local, segundo a tipologia definida pelos Conselhos Estaduais de Meio Ambiente, considerados porte, potencial poluidor e natureza da atividade."}, {"id": 11686, "materia": "ia", "nivel": 4, "enunciado": "A técnica de aprendizado por reforço com feedback humano (RLHF), usada no treinamento de assistentes como os chatbots atuais, serve principalmente para:", "opcoes": ["Alinhar as respostas do modelo às preferências de pessoas", "Aumentar o tamanho da janela de contexto do modelo sem precisar retreiná-lo", "Eliminar por completo a necessidade de dados de treinamento no modelo", "Permitir que o modelo navegue sozinho na internet, sem nenhuma supervisão humana"], "explicacao": "No RLHF, avaliadores humanos comparam respostas, e essas preferências treinam um modelo de recompensa que orienta o ajuste do assistente para respostas mais úteis e seguras."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select materia, nivel, count(*) as questoes_novas from public.questoes where id between 11587 and 11686 group by materia, nivel order by materia, nivel;
select public.questoes_versao() as nova_versao;
